SELECT id, name, parent_id FROM erp_product_category WHERE id BETWEEN 973010 AND 973035 ORDER BY id;
SELECT id, name, category_id, purchase_price FROM erp_product WHERE id IN (972001,972101,972201,972301,972008,972108,972208,972308,972015,972115,972215,972315,972022,972122,972222,972322,972029,972129,972229,972329) ORDER BY id;
SELECT id, bom_id, material_id, material_type, remark FROM erp_bom_item WHERE bom_id IN (972501,972601,972701,972801) ORDER BY id;